(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.012+t*0.15)*8+Math.cos((y+w1y)*0.01-t*0.12)*6;
  const w2y = Math.cos((y+w1y)*0.013-t*0.18)*8+Math.sin((x+w1x)*0.011+t*0.14)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.7],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.6],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75+4)*40,0.085,1.8,1.3],
    [200+Math.sin(t*0.25+6)*110,150+Math.cos(t*0.45+3)*70,0.075,2.4,0.85]
  ];
  let aS=0,iS=0,rS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=1.0/(1.0+d*0.003);
    aS+=(Math.sin(d*f-t*sp)+Math.sin(d*f*1.5-t*sp*0.7))*w*a;
    iS+=(Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.cos(d*f*0.5-t*sp*0.4))*w*a;
    rS+=Math.sin(d*f*0.3+t*sp*0.3+2.0)*w*a*0.5;
  }
  const act=aS/9,inh=iS/9,rip=rS/9;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.5+Math.sin(sx*0.12-sy*0.08+t*2.2)*0.3)/2.8+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.03-ang*2-t*0.8)*0.6+Math.sin(dist*0.07+ang*5-t*2.0)*0.4)*0.25;
  const turing=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-sy*0.18+t*0.7)*0.3)*1.8)*0.35;
  const rd1=act-inh*0.7+bg*0.3+spiral;
  const rd2=Math.tanh(rd1*2.2)+rip*0.4;
  const reaction=Math.tanh(rd2*1.5);
  const blend=reaction*0.65+turing*0.35,v=blend*0.5+0.5;
  const pal=[[6,12,52],[10,45,85],[15,90,115],[20,140,130],[180,175,50],[215,135,60],[195,80,70],[160,45,80],[90,20,70],[30,15,60],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.0+(Math.abs(reaction)-0.65)*0.6:1.0;
  const glow=Math.max(0,Math.sin(reaction*Math.PI)*0.3);
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50)|0)
  ];
}
